    "review your tasks": "\u0645\u0631\u0648\u0631 \u0648\u0638\u0627\u06CC\u0641",
    "arrange your overview": "\u0686\u06CC\u062F\u0645\u0627\u0646 \u0646\u0645\u0627\u06CC \u06A9\u0644\u06CC",
    "reorder panels, change their width, or hide sections. changes are saved automatically.": "\u067E\u0646\u0644\u200C\u0647\u0627 \u0631\u0627 \u062C\u0627\u0628\u0647\u200C\u062C\u0627 \u06A9\u0646\u060C \u0639\u0631\u0636 \u0622\u0646\u200C\u0647\u0627 \u0631\u0627 \u062A\u063A\u06CC\u06CC\u0631 \u0628\u062F\u0647 \u06CC\u0627 \u0628\u062E\u0634\u200C\u0647\u0627 \u0631\u0627 \u067E\u0646\u0647\u0627\u0646 \u06A9\u0646. \u062A\u063A\u06CC\u06CC\u0631\u0627\u062A \u062E\u0648\u062F\u06A9\u0627\u0631 \u0630\u062E\u06CC\u0631\u0647 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F.",
    "coming up": "\u062F\u0631 \u067E\u06CC\u0634 \u0631\u0648",
    "your latest tasks and priorities": "\u0622\u062E\u0631\u06CC\u0646 \u0648\u0638\u0627\u06CC\u0641 \u0648 \u0627\u0648\u0644\u0648\u06CC\u062A\u200C\u0647\u0627",
