    "your theme presets": "\u067E\u06CC\u0634\u200C\u062A\u0646\u0638\u06CC\u0645\u200C\u0647\u0627\u06CC \u067E\u0648\u0633\u062A\u0647",
    "save and quickly reapply your own light or dark appearance.": "\u0638\u0627\u0647\u0631 \u0631\u0648\u0634\u0646 \u06CC\u0627 \u062A\u0627\u0631\u06CC\u06A9 \u062F\u0644\u062E\u0648\u0627\u0647 \u062E\u0648\u062F \u0631\u0627 \u0630\u062E\u06CC\u0631\u0647 \u0648 \u062F\u0648\u0628\u0627\u0631\u0647 \u0627\u0639\u0645\u0627\u0644 \u06A9\u0646.",
