    "you have not saved any custom theme presets yet.": "\u0647\u0646\u0648\u0632 \u0647\u06CC\u0686 \u067E\u0648\u0633\u062A\u0647 \u0633\u0641\u0627\u0631\u0634\u06CC \u0630\u062E\u06CC\u0631\u0647 \u0646\u06A9\u0631\u062F\u0647\u200C\u0627\u06CC.",
    "interface font": "\u0641\u0648\u0646\u062A \u0631\u0627\u0628\u0637 \u06A9\u0627\u0631\u0628\u0631\u06CC",
