    "reduce motion": "\u06A9\u0627\u0647\u0634 \u062D\u0631\u06A9\u062A",
    "reduce non-essential interface animation.": "\u0627\u0646\u06CC\u0645\u06CC\u0634\u0646\u200C\u0647\u0627\u06CC \u063A\u06CC\u0631\u0636\u0631\u0648\u0631\u06CC \u0631\u0627\u0628\u0637 \u06A9\u0627\u0631\u0628\u0631\u06CC \u0631\u0627 \u06A9\u0627\u0647\u0634 \u0628\u062F\u0647.",
    "toggle reduced motion": "\u062A\u063A\u06CC\u06CC\u0631 \u0648\u0636\u0639\u06CC\u062A \u06A9\u0627\u0647\u0634 \u062D\u0631\u06A9\u062A",
    "language & regional format": "\u0632\u0628\u0627\u0646 \u0648 \u0642\u0627\u0644\u0628 \u0645\u0646\u0637\u0642\u0647\u200C\u0627\u06CC",
    "choose the interface language and local currency.": "\u0632\u0628\u0627\u0646 \u0631\u0627\u0628\u0637 \u06A9\u0627\u0631\u0628\u0631\u06CC \u0648 \u0648\u0627\u062D\u062F \u067E\u0648\u0644 \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646.",
