    "usd \u00B7 us dollar": "\u062F\u0644\u0627\u0631 \u0622\u0645\u0631\u06CC\u06A9\u0627 \u00B7 USD",
    "eur \u00B7 euro": "\u06CC\u0648\u0631\u0648 \u00B7 EUR",
    "accessibility": "\u062F\u0633\u062A\u0631\u0633\u200C\u067E\u0630\u06CC\u0631\u06CC",
    "choose a comfortable default text size. five clear presets, no pixel arithmetic.": "\u0627\u0646\u062F\u0627\u0632\u0647 \u0645\u062A\u0646 \u067E\u06CC\u0634\u200C\u0641\u0631\u0636 \u062F\u0644\u062E\u0648\u0627\u0647 \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646. \u067E\u0646\u062C \u0627\u0646\u062F\u0627\u0632\u0647 \u0645\u0634\u062E\u0635 \u0648 \u0633\u0627\u062F\u0647.",
    "text size": "\u0627\u0646\u062F\u0627\u0632\u0647 \u0645\u062A\u0646",
    "text size applies across navigation, forms, tables and content. some dense data views may retain compact labels.": "\u0627\u0646\u062F\u0627\u0632\u0647 \u0645\u062A\u0646 \u062F\u0631 \u0646\u0627\u0648\u0628\u0631\u06CC\u060C \u0641\u0631\u0645\u200C\u0647\u0627\u060C \u062C\u062F\u0648\u0644\u200C\u0647\u0627 \u0648 \u0645\u062D\u062A\u0648\u0627 \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0628\u0631\u062E\u06CC \u0646\u0645\u0627\u0647\u0627\u06CC \u062F\u0627\u062F\u0647 \u0641\u0634\u0631\u062F\u0647 \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u0628\u0631\u0686\u0633\u0628\u200C\u0647\u0627\u06CC \u06A9\u0648\u0686\u06A9\u200C\u062A\u0631\u06CC \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0646\u062F.",
    "current workspace": "\u0641\u0636\u0627\u06CC \u06A9\u0627\u0631\u06CC \u0641\u0639\u0644\u06CC",
    "manage the active workspace and its dashboard panels.": "\u0641\u0636\u0627\u06CC \u06A9\u0627\u0631\u06CC \u0641\u0639\u0644\u06CC \u0648 \u067E\u0646\u0644\u200C\u0647\u0627\u06CC \u062F\u0627\u0634\u0628\u0648\u0631\u062F \u0622\u0646 \u0631\u0627 \u0645\u062F\u06CC\u0631\u06CC\u062A \u06A9\u0646.",
    "save name": "\u0630\u062E\u06CC\u0631\u0647 \u0646\u0627\u0645",
    "dashboard panels": "\u067E\u0646\u0644\u200C\u0647\u0627\u06CC \u062F\u0627\u0634\u0628\u0648\u0631\u062F",
