    "balanced preset": "\u0686\u06CC\u062F\u0645\u0627\u0646 \u0645\u062A\u0639\u0627\u062F\u0644",
    "focus preset": "\u0686\u06CC\u062F\u0645\u0627\u0646 \u062A\u0645\u0631\u06A9\u0632",
