    "e.g. freelance studio": "\u0645\u062B\u0644\u0627\u064B \u0627\u0633\u062A\u0648\u062F\u06CC\u0648\u06CC \u0641\u0631\u06CC\u0644\u0646\u0633\u0631\u06CC",
    "expenses split by category": "\u062A\u0641\u06A9\u06CC\u06A9 \u0647\u0632\u06CC\u0646\u0647\u200C\u0647\u0627 \u0628\u0631 \u0627\u0633\u0627\u0633 \u062F\u0633\u062A\u0647\u200C\u0628\u0646\u062F\u06CC",
