    "locally recorded transactions": "\u062A\u0631\u0627\u06A9\u0646\u0634\u200C\u0647\u0627\u06CC \u062B\u0628\u062A\u200C\u0634\u062F\u0647 \u0628\u0647\u200C\u0635\u0648\u0631\u062A \u0645\u062D\u0644\u06CC",
    "make the space yours": "\u0641\u0636\u0627 \u0631\u0627 \u0645\u0637\u0627\u0628\u0642 \u0633\u0644\u06CC\u0642\u0647 \u062E\u0648\u062F\u062A \u0628\u0633\u0627\u0632",
